#!/usr/bin/env python3
"""Generate the platform design-token files from apps/ios/Design/tokens.json.

    python3 .github/scripts/design_tokens.py          # rewrite the generated files
    python3 .github/scripts/design_tokens.py --check  # exit 1 if they are stale (CI)

Outputs:
    apps/ios/Sources/NetworkCoreAppHost/BrandTokens.swift   (iOS, iPadOS, macOS, widget)
    apps/windows-gui/ui/src/design/tokens.css               (Windows and Linux desktop)

Standard library only, so CI needs nothing but python3.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "apps/ios/Design/tokens.json"
SWIFT_OUT = ROOT / "apps/ios/Sources/NetworkCoreAppHost/BrandTokens.swift"
CSS_OUT = ROOT / "apps/windows-gui/ui/src/design/tokens.css"

THEMES = ("light", "dark", "oled")
HEADER = "Generated by .github/scripts/design_tokens.py from apps/ios/Design/tokens.json. Do not edit."

# Order of BrandPalette's stored color properties; every theme must define each one.
PALETTE_KEYS = (
    "bg", "surface", "raised", "border", "soft", "primary", "onPrimary", "text", "text2", "text3",
    "success", "info", "warning", "danger", "amberText", "chart1", "chart2", "chart3", "chart4",
    "heroStart", "heroEnd",
)
# Desktop CSS variables, in output order.
DESKTOP_KEYS = PALETTE_KEYS + ("side", "main", "primaryHover", "dangerSoft", "cautionBorder", "shadow")
WEIGHTS = {"regular": "regular", "medium": "medium", "semibold": "semibold", "bold": "bold"}
CSS_WEIGHTS = {"regular": 400, "medium": 500, "semibold": 600, "bold": 700}
HEX = re.compile(r"^#[0-9A-Fa-f]{6}$")


def fail(message: str) -> None:
    sys.exit(f"design_tokens: {message}")


def hex_literal(value: str, where: str) -> str:
    if not HEX.match(value):
        fail(f"{where} = {value!r} is not a #RRGGBB color")
    return "0x" + value[1:].upper()


def kebab(name: str) -> str:
    return re.sub(r"(?<=[a-z0-9])([A-Z])", r"-\1", name).lower()


def number(value: float) -> str:
    return str(int(value)) if float(value).is_integer() else repr(float(value))


def swift(tokens: dict) -> str:
    out = [f"// {HEADER}", "// swiftlint:disable all", "", "import SwiftUI", ""]

    out += ["/// Colors that stay the same in every theme: they come straight from the app icon.", "enum Brand {"]
    for name, value in tokens["brand"].items():
        out.append(f"    static let {name} = Color(hex: {hex_literal(value, 'brand.' + name)})")
    out += ["}", ""]

    out += ["extension BrandPalette {"]
    for theme in THEMES:
        colors = tokens["themes"][theme]
        missing = [key for key in PALETTE_KEYS if key not in colors]
        if missing:
            fail(f"themes.{theme} is missing {', '.join(missing)}")
        out.append(f"    static let {theme} = BrandPalette(")
        for key in PALETTE_KEYS:
            out.append(f"        {key}: Color(hex: {hex_literal(colors[key], f'themes.{theme}.{key}')}),")
        out.append(f"        solidBars: {'true' if tokens['solidBars'][theme] else 'false'}")
        out.append("    )")
        out.append("")
    out[-1] = "}"
    out.append("")

    out += ["/// Corner radii in points.", "enum BrandRadius {"]
    for name, value in tokens["radius"].items():
        out.append(f"    static let {name}: CGFloat = {number(value)}")
    out += ["}", ""]

    out += ["/// Spacing steps in points, all multiples of 4.", "enum BrandSpacing {"]
    for name, value in tokens["spacing"].items():
        if value % 4:
            fail(f"spacing.{name} = {value} is not a multiple of 4")
        out.append(f"    static let {name}: CGFloat = {number(value)}")
    out += ["}", ""]

    motion = tokens["motion"]
    out += [
        "/// Animation timings. Views fall back to a plain fade when Reduce Motion is on.",
        "enum BrandMotion {",
        f"    static let micro: Double = {number(motion['microMs'] / 1000)}",
        f"    static let standard: Double = {number(motion['standardMs'] / 1000)}",
        f"    static let emphasis: Double = {number(motion['emphasisMs'] / 1000)}",
        f"    static let connectDraw: Double = {number(motion['connectDrawMs'] / 1000)}",
        "    static let spring = Animation.spring("
        f"response: {number(motion['spring']['response'])}, "
        f"dampingFraction: {number(motion['spring']['dampingFraction'])})",
        "}",
        "",
    ]

    out += ["/// The type scale. Every style scales with Dynamic Type.", "enum BrandFont {"]
    for name, style in tokens["typography"].items():
        weight = WEIGHTS.get(style["weight"])
        if weight is None:
            fail(f"typography.{name}.weight = {style['weight']!r} is unknown")
        out.append(f"    static let {name} = Font.{style['ios']}.weight(.{weight})")
    out += ["}", ""]
    return "\n".join(out)


def css(tokens: dict) -> str:
    out = [f"/* {HEADER} */", ""]
    selectors = {
        "light": ":root",
        "dark": ':root[data-theme="dark"]',
        "oled": ':root[data-theme="oled"]',
    }
    for theme in THEMES:
        values = dict(tokens["themes"][theme])
        values.update(tokens["desktopThemes"].get(theme, {}))
        missing = [key for key in DESKTOP_KEYS if key not in values]
        if missing:
            fail(f"desktop theme {theme} is missing {', '.join(missing)}")
        out.append(selectors[theme] + " {")
        for key in DESKTOP_KEYS:
            value = values[key]
            if key != "shadow":
                hex_literal(value, f"{theme}.{key}")
                value = value.lower()
            out.append(f"  --{kebab(key)}: {value};")
        if theme == "light":
            for name, value in tokens["brand"].items():
                out.append(f"  --brand-{kebab(name)}: {hex_literal(value, 'brand.' + name).replace('0x', '#').lower()};")
            # Short aliases the stylesheet has always used.
            out.append("  --amber: var(--brand-amber);")
            out.append("  --line: var(--brand-line);")
            out.append("  --mint: var(--brand-mint);")
            out.append("  --hero-a: var(--hero-start);")
            out.append("  --hero-b: var(--hero-end);")
            for name, value in tokens["radiusDesktop"].items():
                out.append(f"  --radius-{kebab(name)}: {number(value)}px;")
            for name, value in tokens["spacing"].items():
                out.append(f"  --space-{name}: {number(value)}px;")
            for name, style in tokens["typography"].items():
                out.append(f"  --font-{name}: {CSS_WEIGHTS[style['weight']]} {number(style['desktopPx'])}px/1.4 var(--font-family);")
            motion = tokens["motion"]
            out.append(f"  --fast: {number(motion['microMs'])}ms;")
            out.append(f"  --standard: {number(motion['standardMs'])}ms;")
            out.append(f"  --emphasis: {number(motion['emphasisMs'])}ms;")
            out.append("  color-scheme: light;")
        else:
            out.append("  --hero-a: var(--hero-start);")
            out.append("  --hero-b: var(--hero-end);")
            out.append("  color-scheme: dark;")
        out.append("}")
        out.append("")
    out += [
        "@media (prefers-reduced-motion: reduce) {",
        "  :root { --fast: 0ms; --standard: 0ms; --emphasis: 0ms; }",
        "}",
        "",
    ]
    return "\n".join(out)


def main() -> None:
    check = "--check" in sys.argv[1:]
    tokens = json.loads(SOURCE.read_text(encoding="utf-8"))
    if tokens.get("version") != 2:
        fail("tokens.json version must be 2")
    stale = []
    for path, text in ((SWIFT_OUT, swift(tokens)), (CSS_OUT, css(tokens))):
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current == text:
            continue
        if check:
            stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
            print(f"wrote {path.relative_to(ROOT)}")
    if stale:
        fail("stale generated files: " + ", ".join(stale) + ". Run python3 .github/scripts/design_tokens.py.")


if __name__ == "__main__":
    main()
